import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Repository root (the E2E scripts pass it; the fallback is two folders above this file). */
export const repoRoot =
  process.env.E2E_REPO_ROOT ?? join(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** Everything generated by a run (state, files, logs, report): gitignored. */
export const outputDir = join(repoRoot, 'e2e', '.output');

/** Shared JSON state file; `pnpm screenshots` points it elsewhere so the two runs never mix. */
export const stateFile = process.env.E2E_STATE_FILE ?? join(outputDir, 'state.json');

export const mailpitUrl = process.env.E2E_MAILPIT_URL ?? 'http://localhost:18025';
export const fakeCloudflareUrl = process.env.E2E_FAKE_CF_URL ?? 'http://localhost:18787';

export const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms));
